def summarize(rows, accounts):
    summaries = []
    for account in accounts:
        count = 0
        total = 0
        for row in rows:
            if row["account"] == account:
                count += 1
                total += row["delta"]
        summaries.append({"account": account, "count": count, "total": total})
    return summaries

